#!/usr/bin/env python3
"""A small from-scratch reimplementation of the documented peco CLI behavior."""
import os
import sys
import re
import json
import time
import shlex
import shutil
import signal
import select
import termios
import tty as ttymod
import subprocess
from dataclasses import dataclass, field

VERSION_TEXT = "peco version v0.5.11 (built with go1.25.0)\n"
HELP_TEXT = """
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
"""

BUILTIN_FILTERS = ["IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy"]
VALID_LAYOUTS = {"top-down", "bottom-up", "top-down-query-bottom"}

class PecoError(Exception):
    pass

class ParseError(PecoError):
    def __init__(self, msg, kind="options", show_usage=True):
        super().__init__(msg)
        self.msg = msg
        self.kind = kind
        self.show_usage = show_usage

@dataclass
class Options:
    query: str = ""
    rcfile: str = ""
    version: bool = False
    help: bool = False
    buffer_size: int | None = None
    null: bool = False
    initial_index: int = 0
    initial_filter: str = "IgnoreCase"
    prompt: str = "QUERY>"
    layout: str = "top-down"
    select_1: bool = False
    exit_0: bool = False
    select_all: bool = False
    on_cancel: str = "success"
    selection_prefix: str | None = None
    exec_cmd: str | None = None
    print_query: bool = False
    ansi: bool = False
    height: str | None = None
    # configuration-only knobs
    fuzzy_longest_sort: bool = False
    sticky_selection: bool = False
    suppress_status_msg: bool = False
    keymap: dict = field(default_factory=dict)
    actions: dict = field(default_factory=dict)
    custom_filters: dict = field(default_factory=dict)
    single_key_jump: dict = field(default_factory=dict)
    style: dict = field(default_factory=dict)
    max_scan_buffer_size: int = 256
    # Which CLI options were explicitly set (config must not override them)
    cli_set: set = field(default_factory=set)
    positionals: list = field(default_factory=list)

@dataclass
class Item:
    display_b: bytes
    output_b: bytes
    raw_b: bytes
    index: int
    @property
    def display(self) -> str:
        return self.display_b.decode('utf-8', 'surrogateescape')
    @property
    def output_text(self) -> str:
        return self.output_b.decode('utf-8', 'surrogateescape')

ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[ -/]*[@-~]")

def strip_ansi(s: str) -> str:
    return ANSI_RE.sub("", s)

# ---------------------------------------------------------------------------
# Command line parsing
# ---------------------------------------------------------------------------
VALUE_FLAGS = {
    "query", "rcfile", "buffer-size", "initial-index", "initial-filter",
    "prompt", "layout", "on-cancel", "selection-prefix", "exec", "height",
}
BOOL_FLAGS = {"help", "version", "null", "select-1", "exit-0", "select-all", "print-query", "ansi"}

def parse_int_go(value: str, flag_label: str) -> int:
    try:
        # Go's ParseInt base 0 accepts decimal; Python int base 10 is enough here.
        return int(value, 10)
    except Exception:
        raise ParseError(f"invalid argument for flag `{flag_label}' (expected int): strconv.ParseInt: parsing \"{value}\": invalid syntax")

def set_opt(opts: Options, name: str, value=True):
    opts.cli_set.add(name)
    if name == "query": opts.query = value
    elif name == "rcfile": opts.rcfile = value
    elif name == "version": opts.version = True
    elif name == "help": opts.help = True
    elif name == "buffer-size": opts.buffer_size = parse_int_go(value, "-b, --buffer-size")
    elif name == "null": opts.null = True
    elif name == "initial-index": opts.initial_index = parse_int_go(value, "--initial-index")
    elif name == "initial-filter": opts.initial_filter = value
    elif name == "prompt": opts.prompt = value
    elif name == "layout": opts.layout = value
    elif name == "select-1": opts.select_1 = True
    elif name == "exit-0": opts.exit_0 = True
    elif name == "select-all": opts.select_all = True
    elif name == "on-cancel": opts.on_cancel = value
    elif name == "selection-prefix": opts.selection_prefix = value
    elif name == "exec": opts.exec_cmd = value
    elif name == "print-query": opts.print_query = True
    elif name == "ansi": opts.ansi = True
    elif name == "height": opts.height = value
    else: raise AssertionError(name)

def require_value(argv, i, flag_display):
    if i + 1 >= len(argv):
        raise ParseError(f"expected argument for flag `{flag_display}'")
    nxt = argv[i+1]
    if nxt.startswith('-'):
        raise ParseError(f"expected argument for flag `{flag_display}', but got option `{nxt}'")
    return nxt

def parse_args(argv) -> Options:
    opts = Options()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            # The original parser treats -- as just another positional filename.
            opts.positionals.append(a)
            i += 1
            continue
        if a.startswith("--") and len(a) > 2:
            body = a[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                if name in BOOL_FLAGS:
                    # go-flags accepts --help=something? The common case is not needed;
                    # report it as an unknown/invalid flag-like usage.
                    raise ParseError(f"unknown flag `{name}'")
                if name not in VALUE_FLAGS:
                    raise ParseError(f"unknown flag `{name}'")
                set_opt(opts, name, val)
            else:
                name = body
                if name in BOOL_FLAGS:
                    set_opt(opts, name, True)
                elif name in VALUE_FLAGS:
                    val = require_value(argv, i, "--" + name)
                    set_opt(opts, name, val)
                    i += 1
                else:
                    raise ParseError(f"unknown flag `{name}'")
        elif a.startswith("-") and a != "-":
            # Supported short flags are -h and -b. -b accepts -bVALUE, -b=VALUE or -b VALUE.
            if a == "-h":
                set_opt(opts, "help", True)
            elif a == "-b":
                val = require_value(argv, i, "-b, --buffer-size")
                set_opt(opts, "buffer-size", val)
                i += 1
            elif a.startswith("-b="):
                set_opt(opts, "buffer-size", a[3:])
            elif a.startswith("-b") and len(a) > 2:
                set_opt(opts, "buffer-size", a[2:])
            else:
                # For -hv, the observed parser complains about v rather than h.
                unknown = a[2] if len(a) > 2 and a[1] == 'h' else a[1]
                raise ParseError(f"unknown flag `{unknown}'")
        else:
            opts.positionals.append(a)
        i += 1
    return opts

# ---------------------------------------------------------------------------
# Configuration files
# ---------------------------------------------------------------------------

def simple_yaml_load(text: str):
    """Tiny YAML subset: top-level key: value and one-level maps."""
    root = {}
    stack = [(0, root)]
    for raw in text.splitlines():
        line = raw.rstrip()
        if not line or line.lstrip().startswith('#'):
            continue
        indent = len(line) - len(line.lstrip(' '))
        s = line.strip()
        if ':' not in s:
            continue
        key, val = s.split(':', 1)
        key = key.strip().strip('"\'')
        val = val.strip()
        while stack and indent < stack[-1][0]:
            stack.pop()
        parent = stack[-1][1]
        if val == "":
            d = {}
            parent[key] = d
            stack.append((indent + 2, d))
        else:
            if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                val = val[1:-1]
            elif val.lower() == 'true': val = True
            elif val.lower() == 'false': val = False
            else:
                try: val = int(val)
                except Exception: pass
            parent[key] = val
    return root

def read_config_file(path: str, explicit: bool):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except OSError as e:
        if explicit:
            raise PecoError(f"failed to setup peco: failed to setup configuration: failed to read config file: failed to open file {path}: {e}")
        return None
    try:
        if path.endswith(('.yaml', '.yml')):
            return simple_yaml_load(text)
        return json.loads(text)
    except json.JSONDecodeError as e:
        # Match Go's encoding/json messages for common cases.
        if not text:
            msg = "EOF"
        else:
            msg = e.msg
            if e.pos is not None:
                # Python says "Expecting property name enclosed in double quotes";
                # the Go message for {bad is friendlier to reproduce specially.
                stripped = text.lstrip()
                if stripped.startswith('{') and len(stripped) > 1 and stripped[1:2] not in ('"', '}'):
                    ch = stripped[1]
                    msg = f"invalid character '{ch}' looking for beginning of object key string"
        raise PecoError(f"failed to setup peco: failed to setup configuration: failed to read config file: failed to decode JSON: {msg}")
    except Exception as e:
        raise PecoError(f"failed to setup peco: failed to setup configuration: failed to read config file: {e}")

def find_default_config():
    candidates = []
    xdg_home = os.environ.get('XDG_CONFIG_HOME')
    home = os.environ.get('HOME')
    if xdg_home:
        candidates += [os.path.join(xdg_home, 'peco', 'config.json'), os.path.join(xdg_home, 'peco', 'config.yaml')]
    if home:
        candidates += [os.path.join(home, '.config', 'peco', 'config.json'), os.path.join(home, '.config', 'peco', 'config.yaml')]
    for d in os.environ.get('XDG_CONFIG_DIRS', '').split(':'):
        if d:
            candidates += [os.path.join(d, 'peco', 'config.json'), os.path.join(d, 'peco', 'config.yaml')]
    if home:
        candidates += [os.path.join(home, '.peco', 'config.json'), os.path.join(home, '.peco', 'config.yaml')]
    for p in candidates:
        if os.path.exists(p):
            return p
    return None

def apply_config(opts: Options):
    cfg = None
    if opts.rcfile:
        cfg = read_config_file(opts.rcfile, True)
    else:
        p = find_default_config()
        if p:
            cfg = read_config_file(p, False)
    if not cfg:
        return
    def apply(field_name, attr, transform=lambda x: x):
        if field_name in cfg and attr not in opts.cli_set:
            setattr(opts, attr.replace('-', '_'), transform(cfg[field_name]))
    apply('Prompt', 'prompt', str)
    apply('InitialFilter', 'initial-filter', str)
    apply('OnCancel', 'on-cancel', str)
    apply('ANSI', 'ansi', bool)
    apply('Height', 'height', str)
    apply('SelectionPrefix', 'selection-prefix', str)
    if 'MaxScanBufferSize' in cfg:
        try: opts.max_scan_buffer_size = int(cfg['MaxScanBufferSize'])
        except Exception: pass
    if 'FuzzyLongestSort' in cfg: opts.fuzzy_longest_sort = bool(cfg['FuzzyLongestSort'])
    if 'StickySelection' in cfg: opts.sticky_selection = bool(cfg['StickySelection'])
    if 'SuppressStatusMsg' in cfg: opts.suppress_status_msg = bool(cfg['SuppressStatusMsg'])
    if 'Keymap' in cfg and isinstance(cfg['Keymap'], dict): opts.keymap.update(cfg['Keymap'])
    if 'Action' in cfg and isinstance(cfg['Action'], dict): opts.actions.update(cfg['Action'])
    if 'CustomFilter' in cfg and isinstance(cfg['CustomFilter'], dict): opts.custom_filters.update(cfg['CustomFilter'])
    if 'SingleKeyJump' in cfg and isinstance(cfg['SingleKeyJump'], dict): opts.single_key_jump.update(cfg['SingleKeyJump'])
    if 'Style' in cfg and isinstance(cfg['Style'], dict): opts.style.update(cfg['Style'])

def validate_options(opts: Options):
    if opts.layout not in VALID_LAYOUTS:
        raise PecoError(f"failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line arguments: unknown layout: '{opts.layout}'")
    if opts.on_cancel not in ("success", "error"):
        raise PecoError(f"failed to setup peco: failed to apply configuration: invalid --on-cancel value: invalid OnCancel value \"{opts.on_cancel}\": must be \"success\" or \"error\"")
    if opts.height is not None:
        parse_height_spec(opts.height, check_only=True)
    available = set(BUILTIN_FILTERS) | set(opts.custom_filters.keys())
    if opts.initial_filter not in available:
        raise PecoError("failed to setup peco: failed to apply configuration: failed to populate initial filter: failed to set filter: specified filter was not found")

# ---------------------------------------------------------------------------
# Input and output
# ---------------------------------------------------------------------------

def read_input(opts: Options) -> list[Item]:
    if opts.positionals:
        path = opts.positionals[0]
        try:
            with open(path, 'rb') as f:
                data = f.read()
        except OSError as e:
            raise PecoError(f"failed to setup input source: failed to open file for input: {e}")
    else:
        data = sys.stdin.buffer.read()
    if data == b'':
        lines = []
    else:
        parts = data.split(b'\n')
        if parts and parts[-1] == b'':
            parts = parts[:-1]
        lines = parts
    items = []
    for idx, raw in enumerate(lines):
        if opts.null and b'\x00' in raw:
            disp, out = raw.split(b'\x00', 1)
        else:
            disp, out = raw, raw
        items.append(Item(disp, out, raw, idx))
    if opts.buffer_size is not None and opts.buffer_size >= 0 and len(items) > opts.buffer_size:
        items = items[-opts.buffer_size:]
    return items

def emit_results(opts: Options, query: str, items: list[Item]):
    out = sys.stdout.buffer
    if opts.print_query:
        out.write(query.encode('utf-8', 'surrogateescape') + b'\n')
    for it in items:
        out.write(it.output_b + b'\n')
    out.flush()

# ---------------------------------------------------------------------------
# Filtering
# ---------------------------------------------------------------------------

def parse_query_terms(query: str):
    positives, negatives = [], []
    for tok in query.split():
        if tok == "":
            continue
        if tok.startswith('\\-'):
            positives.append(tok[1:])
        elif tok.startswith('-') and len(tok) > 1:
            negatives.append(tok[1:])
        else:
            positives.append(tok)
    return positives, negatives

def smart_case_sensitive(terms):
    return any(any(ch.isupper() for ch in t) for t in terms)

def fuzzy_match(pattern: str, text: str, case_sensitive: bool) -> bool:
    if not case_sensitive:
        pattern, text = pattern.lower(), text.lower()
    it = iter(text)
    return all(ch in it for ch in pattern)

def regex_search(pattern: str, text: str, flags=0) -> bool:
    return re.search(pattern, text, flags) is not None

def item_text(opts: Options, item: Item) -> str:
    s = item.display
    if opts.ansi:
        s = strip_ansi(s)
    return s

def filter_items(opts: Options, items: list[Item], query: str, current_filter: str, query_enabled: bool=True):
    if not query_enabled or query == "":
        return list(items), None
    if current_filter in opts.custom_filters:
        try:
            return custom_filter_items(opts, items, query, current_filter), None
        except Exception as e:
            return [], str(e)
    positives, negatives = parse_query_terms(query)
    terms = positives + negatives
    if not terms:
        return list(items), None
    results = []
    err = None
    smart_sensitive = smart_case_sensitive(terms)
    for it in items:
        text = item_text(opts, it)
        try:
            if current_filter == "IgnoreCase":
                tl = text.lower()
                ok = all(p.lower() in tl for p in positives) and not any(n.lower() in tl for n in negatives)
            elif current_filter == "CaseSensitive":
                ok = all(p in text for p in positives) and not any(n in text for n in negatives)
            elif current_filter == "SmartCase":
                if smart_sensitive:
                    ok = all(p in text for p in positives) and not any(n in text for n in negatives)
                else:
                    tl = text.lower()
                    ok = all(p.lower() in tl for p in positives) and not any(n.lower() in tl for n in negatives)
            elif current_filter == "Regexp":
                ok = all(regex_search(p, text) for p in positives) and not any(regex_search(n, text) for n in negatives)
            elif current_filter == "IRegexp":
                ok = all(regex_search(p, text, re.I) for p in positives) and not any(regex_search(n, text, re.I) for n in negatives)
            elif current_filter == "Fuzzy":
                ok = all(fuzzy_match(p, text, smart_sensitive) for p in positives)
                # Negative fuzzy terms are regexp-based exclusions in the docs.
                ok = ok and not any(regex_search(n, text, 0 if smart_sensitive else re.I) for n in negatives)
            else:
                ok = True
        except re.error as e:
            err = f"error parsing regexp: {e}: `{query}`"
            ok = False
        if ok:
            results.append(it)
    if opts.fuzzy_longest_sort and current_filter == "Fuzzy" and positives:
        pat = positives[0]
        def score(it):
            t = item_text(opts, it)
            hay = t if smart_sensitive else t.lower(); needle = pat if smart_sensitive else pat.lower()
            # crude: earlier complete subsequence wins; shorter line as tiebreaker.
            pos = []
            start = 0
            for c in needle:
                j = hay.find(c, start)
                if j < 0: j = 10**9
                pos.append(j); start = j + 1
            span = (pos[-1]-pos[0]+1) if pos else 0
            return (span, pos[0] if pos else 0, len(t))
        results.sort(key=score)
    return results, err

def custom_filter_items(opts: Options, items: list[Item], query: str, name: str):
    spec = opts.custom_filters.get(name) or {}
    cmd = spec.get('Cmd') or spec.get('cmd')
    if not cmd:
        return []
    args = spec.get('Args') or spec.get('args') or ["$QUERY"]
    args = [str(a).replace('$QUERY', query) for a in args]
    input_data = b''.join(it.display_b + b'\n' for it in items)
    p = subprocess.run([cmd] + args, input=input_data, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    returned = p.stdout.split(b'\n')
    if returned and returned[-1] == b'':
        returned = returned[:-1]
    # Preserve the custom filter's order and map lines back to existing items.
    buckets = {}
    for it in items:
        buckets.setdefault(it.display_b, []).append(it)
    out = []
    for line in returned:
        bucket = buckets.get(line)
        if bucket:
            out.append(bucket.pop(0))
    return out

# ---------------------------------------------------------------------------
# Terminal UI
# ---------------------------------------------------------------------------

def parse_height_spec(value: str, check_only=False, term_lines=None):
    s = str(value)
    try:
        if s.endswith('%'):
            n = int(s[:-1])
            if n <= 0:
                raise ValueError('nonpositive')
            if term_lines is None: term_lines = shutil.get_terminal_size((80, 24)).lines
            return max(1, int(term_lines * n / 100))
        n = int(s)
        if n <= 0:
            raise ValueError('nonpositive')
        return n + 2  # documented: result lines + prompt + status
    except ValueError as e:
        if str(e) == 'nonpositive':
            raise PecoError(f"failed to setup peco: failed to apply configuration: failed to parse height specification: height must be positive: \"{s}\"")
        raise PecoError(f"failed to setup peco: failed to apply configuration: failed to parse height specification: invalid height specification: \"{s}\"")

DEFAULT_KEYMAP = {
    'Esc': 'peco.Cancel', 'C-c': 'peco.Cancel', 'Enter': 'peco.Finish',
    'C-f': 'peco.ForwardChar', 'C-a': 'peco.BeginningOfLine', 'C-b': 'peco.BackwardChar',
    'C-d': 'peco.DeleteForwardChar', 'C-e': 'peco.EndOfLine', 'C-k': 'peco.KillEndOfLine',
    'C-u': 'peco.KillBeginningOfLine', 'BS': 'peco.DeleteBackwardChar', 'C-8': 'peco.DeleteBackwardChar',
    'C-w': 'peco.DeleteBackwardWord', 'C-g': 'peco.SelectNone', 'C-n': 'peco.SelectDown',
    'C-p': 'peco.SelectUp', 'C-r': 'peco.RotateFilter', 'C-t': 'peco.ToggleQuery',
    'C-Space': 'peco.ToggleSelectionAndSelectNext', 'ArrowUp': 'peco.SelectUp',
    'ArrowDown': 'peco.SelectDown', 'ArrowLeft': 'peco.ScrollPageUp', 'ArrowRight': 'peco.ScrollPageDown',
    'Pgup': 'peco.ScrollPageUp', 'Pgdn': 'peco.ScrollPageDown',
}

KEY_BYTES = {
    'Enter': b'\r', 'Tab': b'\t', 'Esc': b'\x1b', 'BS': b'\x7f', 'BS2': b'\x08',
    'ArrowUp': b'\x1b[A', 'ArrowDown': b'\x1b[B', 'ArrowRight': b'\x1b[C', 'ArrowLeft': b'\x1b[D',
    'Pgup': b'\x1b[5~', 'Pgdn': b'\x1b[6~', 'Delete': b'\x1b[3~', 'Home': b'\x1b[H', 'End': b'\x1b[F',
}
for i in range(1, 27):
    KEY_BYTES[f'C-{chr(ord("a")+i-1)}'] = bytes([i])
# Common aliases/odd controls.
KEY_BYTES['C-Space'] = b'\x00'; KEY_BYTES['C-2'] = b'\x00'
KEY_BYTES['C-['] = b'\x1b'; KEY_BYTES['C-8'] = b'\x7f'; KEY_BYTES['C-?'] = b'\x7f'
KEY_BYTES['C-_'] = b'\x1f'; KEY_BYTES['C-/'] = b'\x1f'; KEY_BYTES['C-]'] = b'\x1d'; KEY_BYTES['C-\\'] = b'\x1c'

def key_name_from_bytes(bs: bytes):
    for name, val in KEY_BYTES.items():
        if bs == val:
            return name
    if len(bs) == 1:
        b = bs[0]
        if 1 <= b <= 26:
            return f'C-{chr(ord("a")+b-1)}'
        if b == 0: return 'C-Space'
        if b == 127: return 'BS'
    return None

def build_keymap(opts: Options):
    km = dict(DEFAULT_KEYMAP)
    for k, v in opts.keymap.items():
        km[str(k)] = v
    return km

def action_sequence(opts: Options, action):
    if isinstance(action, list):
        return action
    if action in opts.actions:
        val = opts.actions[action]
        return val if isinstance(val, list) else [val]
    return [action]

def tty_write(fd, s: str):
    os.write(fd, s.encode('utf-8', 'surrogateescape'))

def visible_width(s: str):
    # Good enough for ASCII; treat other codepoints as width 1.
    return len(strip_ansi(s))

def fit(s: str, width: int):
    if width <= 0:
        return ''
    plain = strip_ansi(s)
    if len(plain) > width:
        return plain[:width]
    return plain + ' ' * (width - len(plain))

def render(fd, opts: Options, items: list[Item], filtered: list[Item], query: str, cursor: int,
           selected_pos: int, saved: set[int], current_filter: str, query_enabled: bool,
           status_msg: str | None, top_item: int, inline: bool):
    size = shutil.get_terminal_size((80, 24))
    cols, rows = size.columns, size.lines
    if opts.height:
        rows = min(rows, parse_height_spec(opts.height, term_lines=size.lines))
    if rows < 3: rows = 3
    result_rows = max(1, rows - 2)
    # Keep selection visible.
    if selected_pos < top_item: top_item = selected_pos
    if selected_pos >= top_item + result_rows: top_item = selected_pos - result_rows + 1
    if top_item < 0: top_item = 0

    def draw_prompt(row):
        prompt = opts.prompt
        left = prompt + ' ' + query
        if not query_enabled:
            left = prompt + ' '  # original hides query from filtering but leaves entered text in many cases; keep simple
        count = len(filtered)
        page = 1
        pos = 1 if count else 1
        status = f"{current_filter} [{count} ({page}/{pos})]"
        if len(left) + len(status) + 1 <= cols:
            line = left + ' ' * (cols - len(left) - len(status)) + status
        else:
            line = left[:cols]
        tty_write(fd, f"\x1b[{row};1H\x1b[0m" + fit(line, cols))
        cur_col = min(cols, len(prompt) + 2 + cursor)
        tty_write(fd, f"\x1b[{row};{max(1, cur_col)}H")

    def draw_status(row):
        msg = '' if opts.suppress_status_msg else (status_msg or '')
        tty_write(fd, f"\x1b[{row};1H\x1b[0m" + fit(msg, cols))

    def draw_results(start_row, reverse=False):
        shown = filtered[top_item:top_item+result_rows]
        if reverse:
            shown = list(reversed(shown))
        for i in range(result_rows):
            row = start_row + i
            if i < len(shown):
                it = shown[i]
                actual_pos = filtered.index(it) if it in filtered else top_item + i
                text = strip_ansi(it.display) if opts.ansi else it.display
                is_current = (actual_pos == selected_pos)
                is_saved = it.index in saved
                if opts.selection_prefix is not None:
                    pref = (opts.selection_prefix + ' ') if (is_current or is_saved) else (' ' * (len(opts.selection_prefix) + 1))
                    line = pref + text
                    tty_write(fd, f"\x1b[{row};1H\x1b[0m" + fit(line, cols))
                else:
                    attr = ''
                    if is_current:
                        attr = '\x1b[45m\x1b[4m'
                    elif is_saved:
                        attr = '\x1b[43m\x1b[1m'
                    tty_write(fd, f"\x1b[{row};1H\x1b[0m{attr}" + fit(text, cols) + "\x1b[0m")
            else:
                tty_write(fd, f"\x1b[{row};1H\x1b[0m" + ' ' * cols)

    if inline:
        # Redraw a compact block at the bottom; no alternate-screen clear.
        base = max(1, size.lines - rows + 1)
        tty_write(fd, "\x1b7")
        if opts.layout == 'bottom-up':
            draw_results(base, reverse=True); draw_prompt(base + result_rows); draw_status(base + result_rows + 1)
        elif opts.layout == 'top-down-query-bottom':
            draw_results(base); draw_prompt(base + result_rows); draw_status(base + result_rows + 1)
        else:
            draw_prompt(base); draw_results(base + 1); draw_status(base + result_rows + 1)
        tty_write(fd, "\x1b8")
    else:
        if opts.layout == 'bottom-up':
            draw_results(1, reverse=True); draw_prompt(result_rows + 1); draw_status(result_rows + 2)
        elif opts.layout == 'top-down-query-bottom':
            draw_results(1); draw_prompt(result_rows + 1); draw_status(result_rows + 2)
        else:
            draw_prompt(1); draw_results(2); draw_status(result_rows + 2)
        # Cursor after prompt.
    return top_item

def read_key(fd):
    try:
        b = os.read(fd, 1)
    except OSError:
        return None, b''
    if not b:
        return None, b''
    if b == b'\x1b':
        seq = b
        end = time.time() + 0.03
        while time.time() < end:
            r, _, _ = select.select([fd], [], [], max(0, end - time.time()))
            if not r:
                break
            try:
                more = os.read(fd, 16)
            except OSError:
                break
            if not more:
                break
            seq += more
            # Most escape sequences are complete when ending in a letter or ~.
            if seq[-1:] in b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz~':
                break
        name = key_name_from_bytes(seq)
        if name:
            return name, seq
        if seq.startswith(b'\x1b') and len(seq) == 2:
            # Alt/Meta key.
            ch = seq[1:2].decode('utf-8', 'ignore')
            if ch:
                return 'M-' + ch, seq
        return 'Esc' if seq == b'\x1b' else None, seq
    # UTF-8 multibyte: gather immediately available continuation bytes.
    if b[0] >= 0x80:
        seq = b
        while True:
            r, _, _ = select.select([fd], [], [], 0.001)
            if not r: break
            seq += os.read(fd, 1)
            try:
                seq.decode('utf-8')
                break
            except UnicodeDecodeError:
                if len(seq) > 4: break
        return None, seq
    name = key_name_from_bytes(b)
    return name, b

def delete_backward_word(q, cur):
    if cur <= 0: return q, cur
    i = cur
    while i > 0 and q[i-1].isspace(): i -= 1
    while i > 0 and not q[i-1].isspace(): i -= 1
    return q[:i] + q[cur:], i

def apply_one_action(action, state):
    opts = state['opts']; filtered = state['filtered']
    q = state['query']; cur = state['cursor']
    # Normalize deprecated aliases.
    aliases = {
        'peco.SelectPreviousPage': 'peco.ScrollPageUp', 'peco.SelectNextPage': 'peco.ScrollPageDown',
        'peco.SelectPrevious': 'peco.SelectUp', 'peco.SelectNext': 'peco.SelectDown',
        'peco.ToggleSelectMode': 'peco.ToggleRangeMode', 'peco.CancelSelectMode': 'peco.CancelRangeMode',
    }
    action = aliases.get(action, action)
    if action == 'peco.Finish': return 'finish'
    if action == 'peco.Cancel': return 'cancel'
    if action == 'peco.ForwardChar': state['cursor'] = min(len(q), cur + 1)
    elif action == 'peco.BackwardChar': state['cursor'] = max(0, cur - 1)
    elif action == 'peco.BeginningOfLine': state['cursor'] = 0
    elif action == 'peco.EndOfLine': state['cursor'] = len(q)
    elif action == 'peco.ForwardWord':
        i = cur
        while i < len(q) and not q[i].isspace(): i += 1
        while i < len(q) and q[i].isspace(): i += 1
        state['cursor'] = i
    elif action == 'peco.BackwardWord':
        _, i = delete_backward_word(q[:cur], cur)
        state['cursor'] = i
    elif action == 'peco.DeleteForwardChar':
        if cur < len(q): state['query'] = q[:cur] + q[cur+1:]; state['dirty'] = True
    elif action == 'peco.DeleteBackwardChar':
        if cur > 0: state['query'] = q[:cur-1] + q[cur:]; state['cursor'] = cur - 1; state['dirty'] = True
    elif action == 'peco.DeleteForwardWord':
        i = cur
        while i < len(q) and q[i].isspace(): i += 1
        while i < len(q) and not q[i].isspace(): i += 1
        state['query'] = q[:cur] + q[i:]; state['dirty'] = True
    elif action == 'peco.DeleteBackwardWord':
        nq, nc = delete_backward_word(q, cur); state['query'] = nq; state['cursor'] = nc; state['dirty'] = True
    elif action == 'peco.KillBeginningOfLine': state['query'] = q[cur:]; state['cursor'] = 0; state['dirty'] = True
    elif action == 'peco.KillEndOfLine': state['query'] = q[:cur]; state['dirty'] = True
    elif action == 'peco.DeleteAll': state['query'] = ''; state['cursor'] = 0; state['dirty'] = True
    elif action == 'peco.SelectDown':
        n = len(filtered)
        if n: state['selected_pos'] = (state['selected_pos'] + 1) % n
    elif action == 'peco.SelectUp':
        n = len(filtered)
        if n: state['selected_pos'] = (state['selected_pos'] - 1) % n
    elif action == 'peco.ScrollPageDown':
        n = len(filtered)
        if n: state['selected_pos'] = min(n-1, state['selected_pos'] + max(1, state['page_size']))
    elif action == 'peco.ScrollPageUp':
        n = len(filtered)
        if n: state['selected_pos'] = max(0, state['selected_pos'] - max(1, state['page_size']))
    elif action == 'peco.ScrollFirstItem': state['selected_pos'] = 0
    elif action == 'peco.ScrollLastItem':
        if filtered: state['selected_pos'] = len(filtered) - 1
    elif action in ('peco.ToggleSelection', 'peco.ToggleSelectionAndSelectNext'):
        if filtered:
            idx = filtered[state['selected_pos']].index
            if idx in state['saved']: state['saved'].remove(idx)
            else: state['saved'].add(idx)
            if action.endswith('AndSelectNext') and len(filtered):
                state['selected_pos'] = min(len(filtered)-1, state['selected_pos'] + 1)
    elif action == 'peco.SelectNone': state['saved'].clear()
    elif action == 'peco.SelectAll':
        state['saved'] = set(it.index for it in filtered)
    elif action == 'peco.SelectVisible':
        start = state.get('top_item', 0); end = start + state.get('page_size', len(filtered))
        state['saved'].update(it.index for it in filtered[start:end])
    elif action == 'peco.InvertSelection':
        allidx = set(it.index for it in filtered); state['saved'] = allidx - state['saved']
    elif action == 'peco.ToggleQuery': state['query_enabled'] = not state['query_enabled']; state['dirty'] = True
    elif action == 'peco.RotateFilter':
        fl = state['filters']; state['filter_idx'] = (state['filter_idx'] + 1) % len(fl); state['current_filter'] = fl[state['filter_idx']]; state['dirty'] = True
    elif action == 'peco.BackToInitialFilter': state['filter_idx'] = 0; state['current_filter'] = state['filters'][0]; state['dirty'] = True
    elif action == 'peco.FreezeResults':
        state['base_items'] = list(filtered); state['query'] = ''; state['cursor'] = 0; state['dirty'] = True
    elif action == 'peco.UnfreezeResults':
        state['base_items'] = state['items']; state['dirty'] = True
    # Range, context, horizontal scrolling, jump mode and refresh are harmless no-ops here.
    return None

def selected_output_items(state):
    opts = state['opts']; filtered = state['filtered']
    if state['saved']:
        by_index = {it.index: it for it in state['items']}
        return [by_index[i] for i in sorted(state['saved']) if i in by_index]
    if filtered and 0 <= state['selected_pos'] < len(filtered):
        return [filtered[state['selected_pos']]]
    return []

def init_screen_or_error():
    term = os.environ.get('TERM')
    if not term:
        raise PecoError("failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set")
    try:
        fd = os.open('/dev/tty', os.O_RDWR | os.O_NOCTTY)
    except OSError as e:
        raise PecoError(f"failed to initialize screen: failed to initialize tcell screen: open /dev/tty: {e.strerror.lower() if e.strerror else e}")
    return fd

def run_exec_command(cmd: str, items: list[Item]):
    data = b''.join(it.output_b + b'\n' for it in items)
    try:
        subprocess.run(cmd, input=data, shell=True)
    except Exception:
        pass

def run_ui(opts: Options, items: list[Item]) -> int:
    fd = init_screen_or_error()
    old = None
    inline = opts.height is not None
    try:
        old = termios.tcgetattr(fd)
        ttymod.setraw(fd)
        if not inline:
            tty_write(fd, "\x1b[?1049h\x1b[H\x1b[2J\x1b[?25l")
        else:
            tty_write(fd, "\x1b[?25l")
        filters = [opts.initial_filter] + [f for f in BUILTIN_FILTERS if f != opts.initial_filter]
        for cf in opts.custom_filters:
            if cf not in filters: filters.append(cf)
        state = {
            'opts': opts, 'items': items, 'base_items': items, 'query': opts.query,
            'cursor': len(opts.query), 'selected_pos': max(0, opts.initial_index), 'saved': set(),
            'current_filter': opts.initial_filter, 'filter_idx': 0, 'filters': filters,
            'filtered': [], 'query_enabled': True, 'dirty': True, 'status': 'Waiting for input...',
            'top_item': 0, 'page_size': max(1, shutil.get_terminal_size((80,24)).lines - 2),
        }
        if opts.select_all and opts.query:
            # A practical interpretation: preselect lines matching the initial query.
            pass
        keymap = build_keymap(opts)
        status_msg = 'Waiting for input...'
        first = True
        while True:
            if state['dirty'] or first:
                state['filtered'], err = filter_items(opts, state['base_items'], state['query'], state['current_filter'], state['query_enabled'])
                if err: status_msg = err
                else: status_msg = '' if not first else 'Waiting for input...'
                if opts.select_all and opts.query and first:
                    state['saved'] = set(it.index for it in state['filtered'])
                if state['selected_pos'] < 0: state['selected_pos'] = 0
                if state['filtered']:
                    if state['selected_pos'] >= len(state['filtered']): state['selected_pos'] = len(state['filtered']) - 1
                else:
                    state['selected_pos'] = 0
                state['dirty'] = False
                first = False
            size = shutil.get_terminal_size((80,24))
            rows = parse_height_spec(opts.height, term_lines=size.lines) if opts.height else size.lines
            state['page_size'] = max(1, rows - 2)
            state['top_item'] = render(fd, opts, state['items'], state['filtered'], state['query'], state['cursor'],
                                       state['selected_pos'], state['saved'], state['current_filter'], state['query_enabled'],
                                       status_msg, state['top_item'], inline)
            name, raw = read_key(fd)
            if raw == b'':
                return 0
            action = keymap.get(name) if name else None
            # Config keymaps can bind literal printable keys.
            if action is None and raw and len(raw) == 1:
                chtry = raw.decode('utf-8', 'ignore')
                if chtry in keymap: action = keymap[chtry]
            result = None
            if action:
                for act in action_sequence(opts, action):
                    result = apply_one_action(act, state)
                    if result in ('finish', 'cancel'):
                        break
            else:
                # Insert printable text into query.
                try:
                    text = raw.decode('utf-8')
                except Exception:
                    text = ''
                if text and all((ord(c) >= 32 and c != '\x7f') for c in text):
                    q = state['query']; cur = state['cursor']
                    state['query'] = q[:cur] + text + q[cur:]
                    state['cursor'] = cur + len(text)
                    state['dirty'] = True
            if result == 'finish':
                if opts.exec_cmd:
                    run_exec_command(opts.exec_cmd, selected_output_items(state))
                    continue
                out_items = selected_output_items(state)
                # Restore before printing result.
                break
            if result == 'cancel':
                out_items = None
                break
        return_code = 0
        # Restore terminal before output.
        if old is not None: termios.tcsetattr(fd, termios.TCSADRAIN, old)
        tty_write(fd, "\x1b[?25h\x1b[0m")
        if not inline:
            tty_write(fd, "\x1b[H\x1b[2J\x1b[?1049l")
        else:
            tty_write(fd, "\r\n")
        if out_items is None:
            return 1 if opts.on_cancel == 'error' else 0
        emit_results(opts, state['query'], out_items)
        return return_code
    finally:
        try:
            if old is not None:
                termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception:
            pass
        try:
            tty_write(fd, "\x1b[?25h\x1b[0m")
        except Exception:
            pass
        try: os.close(fd)
        except Exception: pass

# ---------------------------------------------------------------------------
# Program entry
# ---------------------------------------------------------------------------

def print_parse_error(e: ParseError):
    sys.stderr.write(e.msg + "\n")
    if e.show_usage:
        sys.stderr.write(HELP_TEXT)
    sys.stderr.write(f"Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line {e.kind}: {e.msg}\n")

def main(argv=None):
    if argv is None: argv = sys.argv[1:]
    try:
        opts = parse_args(argv)
        # help/version short-circuit after command-line parsing but before config/input.
        if opts.help:
            sys.stdout.write(HELP_TEXT)
            return 0
        if opts.version:
            sys.stdout.write(VERSION_TEXT)
            return 0
        apply_config(opts)
        validate_options(opts)
        items = read_input(opts)
        if opts.exit_0 and len(items) == 0:
            return 1
        if opts.select_all and not opts.query:
            emit_results(opts, opts.query, items)
            return 0
        if opts.select_1 and len(items) == 1:
            emit_results(opts, opts.query, items)
            return 0
        return run_ui(opts, items)
    except ParseError as e:
        print_parse_error(e)
        return 1
    except PecoError as e:
        sys.stderr.write(f"Error: {e}\n")
        return 1
    except KeyboardInterrupt:
        return 1
    except BrokenPipeError:
        return 1

if __name__ == '__main__':
    sys.exit(main())
PY
